// Redemption codes and offer availability.

// 32 symbols without 0/O, 1/I: easy to read aloud and type at a till.
export const CODE_ALPHABET = '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
export const CODE_LENGTH = 10; // 50 bits
export const PAYLOAD_PREFIX = 'WRD1-';

/** A new redemption code from cryptographically secure random bytes. */
export function generateCode(randomBytes = (n) => crypto.getRandomValues(new Uint8Array(n))) {
  const bytes = randomBytes(CODE_LENGTH);
  let out = '';
  for (let i = 0; i < CODE_LENGTH; i++) out += CODE_ALPHABET[bytes[i] & 31];
  return out;
}

export function formatCode(code) {
  return `${code.slice(0, 5)}-${code.slice(5)}`;
}

/**
 * Normalise what staff typed or scanned: the bare code, the formatted code, a
 * QR payload (WRD1-XXXXXXXXXX) or a validation URL with ?code=. Returns null
 * if it isn't a well-formed code.
 */
export function normaliseCode(input) {
  if (typeof input !== 'string') return null;
  let s = input.trim();
  const m = s.match(/[?&#]code=([^&#\s]+)/i);
  if (m) s = decodeURIComponent(m[1]);
  s = s.toUpperCase().replace(/^WRD1-/, '').replace(/[\s-]/g, '');
  if (s.length !== CODE_LENGTH) return null;
  for (const ch of s) if (!CODE_ALPHABET.includes(ch)) return null;
  return s;
}

export async function sha256Hex(text) {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

const LONDON = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/London', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', weekday: 'short', hourCycle: 'h23'
});
const DOW = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };

/** London wall-clock parts: {date: 'YYYY-MM-DD', minutes: 0–1439, dow: 1 (Mon)–7 (Sun), month: 'YYYY-MM'}. */
export function londonParts(at = new Date()) {
  const p = Object.fromEntries(LONDON.formatToParts(at).map((x) => [x.type, x.value]));
  return {
    date: `${p.year}-${p.month}-${p.day}`,
    month: `${p.year}-${p.month}`,
    minutes: Number(p.hour) * 60 + Number(p.minute),
    dow: DOW[p.weekday]
  };
}

export const londonDate = (at = new Date()) => londonParts(at).date;

function toMinutes(hhmm) {
  const m = /^(\d{2}):(\d{2})$/.exec(hhmm ?? '');
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

/** Whether London time `at` is inside an offer's daily window (and allowed weekday). */
export function inDailyWindow(offer, at = new Date()) {
  const { minutes, dow } = londonParts(at);
  if (Array.isArray(offer.days) && offer.days.length && !offer.days.includes(dow)) return false;
  const start = toMinutes(offer.window_start), end = toMinutes(offer.window_end);
  if (start === null || end === null) return true;
  return start <= end ? minutes >= start && minutes < end : minutes >= start || minutes < end; // overnight
}

/**
 * Can this player reserve this offer right now?
 *   counts: {reserved, redeemed} units across all players; userCount: this player's active + redeemed
 * Returns {ok, reason, remaining}.
 */
export function offerAvailability(offer, { at = new Date(), reserved = 0, redeemed = 0, userCount = 0, merchantStatus = 'approved' } = {}) {
  const remaining = Math.max(0, offer.quantity_total - reserved - redeemed);
  const fail = (reason) => ({ ok: false, reason, remaining });
  if (merchantStatus !== 'approved') return fail('merchant_unavailable');
  if (offer.status !== 'active') return fail('offer_not_active');
  if (offer.valid_from && at < new Date(offer.valid_from)) return fail('not_started');
  if (offer.valid_until && at >= new Date(offer.valid_until)) return fail('ended');
  if (!inDailyWindow(offer, at)) return fail('outside_window');
  if (remaining <= 0) return fail('sold_out');
  if (offer.max_per_customer && userCount >= offer.max_per_customer) return fail('limit_reached');
  return { ok: true, reason: null, remaining };
}

/** When a new reservation's code stops working. */
export function reservationExpiry(offer, at = new Date(), defaultMinutes = 30) {
  const hold = offer.hold_minutes || defaultMinutes;
  let t = at.getTime() + hold * 60_000;
  if (offer.valid_until) t = Math.min(t, new Date(offer.valid_until).getTime());
  return new Date(t);
}
